```1:85:g:\.00.Tam-duc\Global.asax.cs
using System;
using System.Collections.Generic;

using System.Web;
using System.Web.Security;
using System.Web.SessionState;
using DCore;
using InformationWebObject;
using System.Data;

namespace InformationWeb
{
    public class Global : System.Web.HttpApplication
    {

        protected void Application_Start(object sender, EventArgs e)
        {
            //Application["Random"] = new Random().Next(100);
            Application["Counter"] = Application["Online"] = 1;// Application["Random"];
            GetInfo();
        }
        protected void Session_Start(object sender, EventArgs e)
        {
            //Session.Timeout = 180;
            Application.Lock();
            try
            {
                Application["Counter"] = Convert.ToInt32(Application["Counter"]) + 1;
                Application["Online"] = Convert.ToInt32(Application["Online"]) + 1;
            }
            catch { }
            Application.UnLock();

        }
        protected void Session_End(object sender, EventArgs e)
        {
            Application.Lock();
            try
            {
                Application["Online"] = Convert.ToInt32(Application["Online"]) - 1;
            }
            catch { }
            Application.UnLock();
        }
        protected void Application_End(object sender, EventArgs e)
        {
            Save();
        }
        private void GetInfo()
        {
            DataTable dtb = new SYS_Counter().GetAll();
            if (dtb != null && dtb.Rows.Count > 0)
            {
                Application.Lock();
                Application["Counter"] = Convert.ToInt32(dtb.Rows[0]["Counter"]);
                Application["WebCounterID"] = Convert.ToInt32(dtb.Rows[0]["ID"]);
                Application.UnLock();
            }

        }

        private void Save()
        {
            SYS_Counter item = new SYS_Counter();
            try
            {
                if (Application["CountThisDay"] != null)
                    item.CountThisDay = Convert.ToInt32(Application["CountThisDay"]);
                if (Application["CountThisMonth"] != null)
                    item.CountThisMonth = Convert.ToInt32(Application["CountThisMonth"]);
                if (Application["Counter"] != null)
                    item.Counter = Convert.ToInt32(Application["Counter"]);// -Convert.ToInt32(Application["Random"]);
            }
            catch { }

            if (Application["WebCounterID"] != null)
            {
                item.ID = Convert.ToInt32(Application["WebCounterID"]);
                item.Update();
            }
            else
                item.Add();
        }
    }
}
```

**Key finding:** Global.asax.cs does **NOT** contain any URL routing or rewrite logic. It only handles visitor counter tracking via `Application["Counter"]` and `Application["Online"]`. All URL rewriting is handled by the `UrlRewritingNet.UrlRewriter` HTTP module registered in `Web.config`.

