### `g:\.00.Tam-duc\Pages\InfoSection\InfoSectionDetailRouter.aspx.cs`
**Full path:** `g:\.00.Tam-duc\Pages\InfoSection\InfoSectionDetailRouter.aspx.cs`

```1:126:g:\.00.Tam-duc\Pages\InfoSection\InfoSectionDetailRouter.aspx.cs
using System;
using System.Data;
using System.Web;
using InformationWebObject;
using WebGlobal;

namespace InformationWeb.Pages.InfoSection
{
    public partial class InfoSectionDetailRouter : System.Web.UI.Page
    {
        /// <summary>Key prefix for detail DataTable shared với Detail2/Detail4 để tránh gọi DB 2 lần.</summary>
        public const string ContextKeyDetail = "NewsDetail_";

        protected void Page_Load(object sender, EventArgs e)
        {
            // Phải chạy mỗi request (kể cả postback) để L1/L2 visible đúng và Context có data
            RouteByInformationType();
        }

        /// <summary>Prefix URL xem thử từ CMS — không phải category trong DB.</summary>
        private const string PreviewCategoryLink = "xem-thu-bai-viet";

        private void RouteByInformationType()
        {
            string slug = (Request.QueryString["slug"] ?? "").Trim();
            if (string.IsNullOrEmpty(slug))
            {
                InformationWeb.NotFoundHelper.TransferToNotFound();
                return;
            }

            string cate = (Request.QueryString["cate"] ?? "").Trim().Trim('/');

            // /xem-thu-bai-viet/{slug} — thư mục ảo preview, không validate category
            if (string.Equals(cate, PreviewCategoryLink, StringComparison.OrdinalIgnoreCase))
            {
                Server.Transfer(
                    "~/Pages/InfoSection/InfoSectionDetail5.aspx?slug=" + Uri.EscapeDataString(slug),
                    false);
                return;
            }

            if (InformationWeb.NotFoundHelper.HasDuplicateAdjacentPathSegments(cate))
            {
                InformationWeb.NotFoundHelper.TransferToNotFound();
                return;
            }

            int lang = ResManager.CurrentLanguageID;
            var info = new INFO_Information();

            // 1) Lấy InformationTypeID (proc nhẹ) để quyết định layout
            DataTable dtType = info.GetDataTable(
                "INFO_Information_HOS_News",
                "@InformationLink", slug,
                "@LanguageID", lang,
                "@Top", 1
            );

            if (dtType == null || dtType.Rows.Count == 0)
            {
                InformationWeb.NotFoundHelper.TransferToNotFound();
                return;
            }

            int informationTypeId = 0;
            if (dtType.Columns.Contains("InformationTypeID"))
                int.TryParse(Convert.ToString(dtType.Rows[0]["InformationTypeID"]), out informationTypeId);

            bool isFull = (informationTypeId == 7);
            L2_Full.Visible = isFull;
            L1_Left_Right.Visible = !isFull;

            // 2) Gọi 1 lần proc detail, đẩy vào Context để Detail2/Detail4 dùng lại (tránh gọi DB 2 lần)
            DataTable dtDetail = info.GetDataTable(
                "HOS_NewsDetail2_GetDetail",
                "@InformationLink", slug,
                "@LanguageID", lang
            );
            if (dtDetail == null || dtDetail.Rows.Count == 0)
            {
                InformationWeb.NotFoundHelper.TransferToNotFound();
                return;
            }

            DataRow detailRow = dtDetail.Rows[0];

            // Công bố thông tin (cate 374): chuẩn URL phải là /slug/ (không /cong-bo-thong-tin/slug)
            int categoryId = 0;
            if (detailRow.Table.Columns.Contains("CategoryID") && detailRow["CategoryID"] != DBNull.Value && detailRow["CategoryID"] != null)
                int.TryParse(Convert.ToString(detailRow["CategoryID"]), out categoryId);
            const int CongBoThongTinCategoryId = 374;
            if (categoryId == CongBoThongTinCategoryId)
            {
                string canonicalPath = "/" + slug.Trim('/') + "/";
                if (!string.IsNullOrEmpty(cate))
                {
                    if (string.Equals(cate, "cong-bo-thong-tin", StringComparison.OrdinalIgnoreCase))
                    {
                        Response.RedirectPermanent(canonicalPath, true);
                        return;
                    }
                    InformationWeb.NotFoundHelper.TransferToNotFound();
                    return;
                }
                // Path đúng dạng /slug nhưng thiếu dấu / cuối → redirect /slug/
                // Dùng RawUrl (path gốc client request); Request.Url có thể là path đã rewrite → gây loop
                string rawPath = (Request.RawUrl ?? "").Split('?')[0].Trim();
                if (!rawPath.EndsWith("/", StringComparison.Ordinal))
                {
                    Response.RedirectPermanent(canonicalPath, true);
                    return;
                }
            }
            else if (!string.IsNullOrEmpty(cate)
                && !InformationWeb.NotFoundHelper.IsDetailCategoryUrlValid(cate, detailRow))
            {
                InformationWeb.NotFoundHelper.TransferToNotFound();
                return;
            }

            string contextKey = ContextKeyDetail + lang + "_" + slug;
            HttpContext.Current.Items[contextKey] = dtDetail;
        }
    }
}
```

